     *         TimeZone, Locale)} to explicitly set the locale as well as the
     *         time zone.
     */
    public static TickUnitSource createStandardDateTickUnits(TimeZone zone) {
        return createStandardDateTickUnits(zone, Locale.getDefault());
    }

