            category=DeprecationWarning,
            message=(
                "twisted.web.http.Request.%(old)s was deprecated in "
                "Twisted 13.2.0: Please use twisted.web.http.Request."
                "%(new)s instead." % dict(old=old, new=new)),
            stacklevel=3)


    @property
    def headers(self):
