            self.requestHeaders = headers = Headers()
            for k, v in value.items():
                headers.setRawHeaders(k, [v])
            self._warnHeaders("received_headers", "requestHeaders")
        elif name == 'headers':
            self.responseHeaders = headers = Headers()
            for k, v in value.items():
